static const u8 *ime_glyph(u32 cp) {
    int lo = 0, hi = (int)(sizeof(ime_glyphs) / sizeof(ime_glyphs[0])) - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (ime_glyphs[mid].cp == cp) return ime_glyphs[mid].bmp;
        if (ime_glyphs[mid].cp < cp) lo = mid + 1;
        else hi = mid - 1;
    }
    return 0;
}

